<?php
require __DIR__.'/../admin.php';if(!admin_can('sale')){http_response_code(403);exit('Permission denied.');}$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{sc_admin_guard('sale','update',$_POST);$id=filter_var($_POST['user_id']??0,FILTER_VALIDATE_INT);$active=filter_var($_POST['active']??-1,FILTER_VALIDATE_INT);if(!$id||!in_array($active,[0,1],true))throw new RuntimeException('Invalid customer action.');sc_query('UPDATE online_users SET is_active=? WHERE id=? AND is_deleted=0','ii',[$active,$id]);sc_audit($active?'customer.enabled':'customer.disabled',$id);$notice='Customer access updated.';}catch(Throwable $e){$error=$e instanceof mysqli_sql_exception?'Could not update customer access.':$e->getMessage();}}
$q=mb_substr(trim($_GET['q']??''),0,100);$page=max(1,(int)($_GET['p']??1));$needle='%'.addcslashes($q,'%_\\').'%';$where=' WHERE is_deleted=0';$types='';$params=[];if($q!==''){$where.=" AND (CONCAT(first_name,' ',last_name) LIKE ? OR email LIKE ? OR phone LIKE ?)";$types='sss';$params=[$needle,$needle,$needle];}$total=(int)sc_query('SELECT COUNT(*) n FROM online_users'.$where,$types,$params)->get_result()->fetch_assoc()['n'];$page=min($page,max(1,(int)ceil($total/25)));$rows=sc_query('SELECT id,first_name,last_name,email,phone,is_active,registered_on FROM online_users'.$where.' ORDER BY id DESC LIMIT 25 OFFSET '.(($page-1)*25),$types,$params)->get_result();$id=(int)($_GET['id']??0);
admin_console_open('Online Users');if($notice)echo '<p class="alert alert-success">'.sc_e($notice).'</p>';if($error)echo '<p class="alert alert-danger">'.sc_e($error).'</p>';
if($id){$customer=sc_query('SELECT id,first_name,last_name,email,phone,address,address_city,address_pin,is_active,registered_on FROM online_users WHERE id=? AND is_deleted=0','i',[$id])->get_result()->fetch_assoc();if($customer){$stats=sc_query("SELECT COUNT(*) orders,COALESCE(SUM(CASE WHEN status<>'cancelled' THEN total ELSE 0 END),0) total FROM web_orders WHERE online_user_id=?",'i',[$id])->get_result()->fetch_assoc();echo '<section class="card p-4 mb-4"><h2 class="h4">'.sc_e($customer['first_name'].' '.$customer['last_name']).'</h2><p>'.sc_e($customer['email']).' | '.sc_e($customer['phone']).'</p><p>Registered '.sc_e($customer['registered_on']).' | Orders: '.(int)$stats['orders'].' | Ordered value: '.sc_money((int)round($stats['total']*100)).'</p><a href="'.sc_url('admin/online-orders/?customer='.$id).'">View customer orders</a></section>';}}
?>
<form method="get" class="sc-list-tools"><label>Search customers<input type="search" name="q" value="<?= sc_e($q) ?>" placeholder="Name, email or phone"></label><button class="btn btn-primary">Search</button></form><div class="card p-3"><div class="table-responsive"><table class="table" data-info="ignore-dt"><thead><tr><th>Customer</th><th>Email / Phone</th><th>Registered</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php while($u=$rows->fetch_assoc()): ?><tr><td><a href="?id=<?= $u['id'] ?>&view"><?= sc_e($u['first_name'].' '.$u['last_name']) ?></a></td><td><?= sc_e($u['email']) ?><br><?= sc_e($u['phone']) ?></td><td><?= sc_e($u['registered_on']) ?></td><td><?= $u['is_active']?'Active':'Disabled' ?></td><td><a href="<?= sc_url('admin/online-orders/?customer='.$u['id']) ?>">Orders</a><?php if(admin_can('sale','update')): ?><form method="post"><?= sc_token() ?><input type="hidden" name="user_id" value="<?= $u['id'] ?>"><input type="hidden" name="active" value="<?= $u['is_active']?0:1 ?>"><button class="btn btn-sm btn-outline-secondary mt-2"><?= $u['is_active']?'Disable access':'Enable access' ?></button></form><?php endif; ?></td></tr><?php endwhile; ?></tbody></table></div><nav class="sc-list-pager"><span><?= $total ?> customers | page <?= $page ?></span><a href="?<?= sc_e(http_build_query(['q'=>$q,'p'=>max(1,$page-1)])) ?>">Previous</a><a href="?<?= sc_e(http_build_query(['q'=>$q,'p'=>$page+1])) ?>">Next</a></nav></div><?php admin_console_close(); ?>
